for ri in range(4):
    row_out = []
    for cj in range(4):
        vals = []
        for i in range(row_ranges[ri][0], row_ranges[ri][1] + 1):
            for j in range(col_ranges[cj][0], col_ranges[cj][1] + 1):
                if test_grid[i][j] != 8:
                    vals.append(test_grid[i][j])

        c = Counter(vals)
        if len(c) == 1:
            # Pure: output whichever value is present
            val = list(c.keys())[0]
            row_out.append(val)
        else:
            # Mixed: check minority counts
